});

// Функция для получения случайного NPC в мире
function getRandomNpc() {
  return NPCS[Math.floor(Math.random() * NPCS.length)];
}

// Функция для квеста Валентина
function valentinQuest() {
  const targetNpc = getRandomNpc();
  const player = getPlayer(); // функция для получения игрока

  // Логика принятия квеста
  if (player.hasQuest('valentinQuest')) {
    console.log('Вы уже выполняете квест Валентина');
    return;
  }

  player.hasQuest('valentinQuest', true);
  console.log('Валентин: Привет, мне нужна твоя помощь. Отведи это сообщение другому NPC.');

  // Логика выполнения квеста
  if (player.completedQuest('valentinQuest')) {
    console.log('Валентин: Отличная работа! Ты выполнил квест.');
    player.reward(500); // награда за выполнение квеста
    player.hasQuest('valentinQuest', false);
  }
}

// Функция для диалога с Валентином
function talkToValentin() {
  const player = getPlayer();

  if (player.hasQuest('valentinQuest')) {
    console.log('Валентин: Как ты справишься с квестом?');
  } else {
    valentinQuest();
  }
}

// Добавляем слушатель события для диалога с Валентином
document.addEventListener('talkToValentin', talkToValentin);
